figCss:
/* inline SVG figure palette, follows the light/dark theme */
.fig text {
  font-family: var(--font-sans);
}
.fig .fig-title {
  font-family: var(--font-display);
  font-weight: 650;
  fill: var(--mek-ink);
}
.fig .fig-ink {
  fill: var(--mek-ink);
}
.fig .fig-soft {
  fill: var(--mek-soft);
}
.fig .fig-faint {
  fill: var(--mek-faint);
}
.fig .fig-line {
  fill: none;
  stroke: var(--mek-line-strong);
}
.fig .fig-grid {
  fill: none;
  stroke: var(--mek-line);
}
.fig .fig-box {
  fill: none;
  stroke: var(--mek-line-strong);
}
.fig .fig-tint {
  fill: color-mix(in srgb, var(--mek-ink) 5%, transparent);
  stroke: var(--mek-line-strong);
}
.fig .fig-accent-box {
  fill: color-mix(in srgb, var(--mek-accent) 12%, transparent);
  stroke: var(--mek-accent);
}
.fig .fig-accent-line {
  fill: none;
  stroke: var(--mek-accent);
}
.fig .fig-accent-fill {
  fill: var(--mek-accent);
}
.fig .fig-accent-soft {
  fill: color-mix(in srgb, var(--mek-accent) 30%, transparent);
  stroke: var(--mek-accent);
}
.fig .fig-muted-fill {
  fill: var(--mek-line-strong);
}
.fig .fig-muted-soft {
  fill: color-mix(in srgb, var(--mek-line-strong) 18%, transparent);
  stroke: var(--mek-line-strong);
}
.fig .mono text,
.fig text.mono {
  font-family: var(--font-mono);
}
